<script setup>
import { ref } from 'vue';
import { Head, Link, useForm } from '@inertiajs/vue3';
import axios from 'axios';
import Layout from '@/Layouts/MarketplaceLayout.vue';
import DiscoveryMap from '@/Components/Marketplace/DiscoveryMap.vue';
const props=defineProps({service:String,listing:Object,types:Array,approved:Boolean});
const form=useForm({title:props.listing?.title||'',description:props.listing?.description||'',type:props.listing?.type||props.types[0],price:props.listing?.price??'',priceUnit:props.listing?.priceUnit||({spaces:'month',haul:'day',raketeer:'job'}[props.service]),status:props.listing?.status||'draft',location:{lat:props.listing?.location.lat??12.0,lng:props.listing?.location.lng??124.75,address:props.listing?.location.address||'',city:props.listing?.location.city||''},photos:props.listing?.photos||[],details:props.listing?.details?.brand?props.listing.details:{brand:'',model:'',year:new Date().getFullYear()}});
const uploading=ref(false),uploadError=ref('');
function save(){const url=`/my-listings/${props.service}`;if(props.listing)form.put(url+'/'+props.listing.id);else form.post(url);}
async function upload(e){uploadError.value='';const files=Array.from(e.target.files||[]);if(files.length+form.photos.length>12){uploadError.value='You can add up to 12 photos.';return;}uploading.value=true;try{for(const photo of files){const data=new FormData();data.append('photo',photo);const response=await axios.post('/listing-photos',data);form.photos.push(response.data.url);}}catch(error){uploadError.value=error.response?.data?.message||'Upload failed. Please try again.';}finally{uploading.value=false;e.target.value='';}}
function locate(){navigator.geolocation?.getCurrentPosition(p=>{form.location.lat=p.coords.latitude;form.location.lng=p.coords.longitude;},()=>uploadError.value='Could not get location. Set the point on the map instead.',{timeout:10000});}
</script>
<template><Layout><Head :title="listing?'Edit listing':'Create listing'"/><main class="content form-content"><Link href="/my-listings" class="text-button">← My listings</Link><h1>{{ listing?'Edit your listing.':'Share something nearby.' }}</h1><p>{{ service==='spaces'?'A space to live or work.':service==='haul'?'A vehicle for the next journey.':'A skill your neighborhood needs.' }}</p>
<div v-if="Object.keys(form.errors).length" role="alert" class="notice error"><p v-for="(error,key) in form.errors" :key="key">{{ error }}</p></div>
<form @submit.prevent="save" class="listing-form"><section class="form-section"><h2>01 · The essentials</h2><label>Title<input v-model="form.title" required maxlength="255" placeholder="Give your listing a clear, helpful title"/></label><label>Description<textarea v-model="form.description" required rows="5" maxlength="10000" placeholder="What should someone know before they choose this listing?"/></label><div class="field-row"><label>Type<select v-model="form.type"><option v-for="type in types" :value="type">{{ type.replace(/([A-Z])/g,' $1') }}</option></select></label><label>Price (PHP)<input v-model="form.price" type="number" required min="0" max="99999999.99" step="0.01"/></label><label v-if="service==='raketeer'">Per<select v-model="form.priceUnit"><option value="job">Job</option><option value="hour">Hour</option></select></label></div><div v-if="service==='haul'" class="field-row"><label>Brand<input v-model="form.details.brand" required/></label><label>Model<input v-model="form.details.model" required/></label><label>Year<input v-model="form.details.year" type="number" min="1950" :max="new Date().getFullYear()+1" required/></label></div></section>
<section class="form-section"><h2>02 · Location</h2><p>Choose where this listing appears. For a raket, use the center of the area you serve.</p><label>Address / service area<input v-model="form.location.address" required maxlength="255"/></label><label v-if="service==='spaces'">City<input v-model="form.location.city" maxlength="255"/></label><div class="field-row"><label>Latitude<input v-model.number="form.location.lat" type="number" min="-90" max="90" step="any" required/></label><label>Longitude<input v-model.number="form.location.lng" type="number" min="-180" max="180" step="any" required/></label><button type="button" class="button" @click="locate">Use my location</button></div><DiscoveryMap pick :center="[Number(form.location.lat),Number(form.location.lng)]" :listings="[{id:'location',title:'Listing location',price:Number(form.price)||0,location:form.location}]" @pick="([lat,lng])=>{form.location.lat=lat;form.location.lng=lng;}"/></section>
<section class="form-section"><h2>03 · Photos</h2><p>Up to 12 JPG, PNG, or WebP photos, 5 MB each. The first photo is the cover.</p><label class="upload">{{ uploading?'Uploading…':'Choose photos' }}<input type="file" accept="image/jpeg,image/png,image/webp" multiple :disabled="uploading" @change="upload"/></label><p v-if="uploadError" role="alert" class="error">{{ uploadError }}</p><div class="photo-grid"><div v-for="(photo,i) in form.photos" :key="photo"><img :src="photo" :alt="`Photo ${i+1}`"/><button type="button" class="button" @click="form.photos.splice(i,1)">Remove</button></div></div></section>
<section class="form-section"><h2>04 · Ready when you are</h2><p v-if="!approved">You can save a draft now. Apply from My listings to get approved for publishing.</p><label>Status<select v-model="form.status"><option value="draft">Draft — only visible to you and administrators</option><option v-if="approved" value="active">Published — visible in search</option><option value="reserved">{{ service==='raketeer'?'Busy':service==='haul'?'Maintenance':'Reserved' }} — hidden from search</option><option v-if="service!=='raketeer'" value="rented">Rented — hidden from search</option><option v-if="service==='spaces'" value="archived">Archived — hidden from search</option></select></label><div class="actions"><button class="button primary" :disabled="form.processing||uploading">{{ form.processing?'Saving…':'Save listing' }}</button><Link href="/my-listings" class="button">Cancel</Link></div></section></form></main></Layout></template>
